case "calendar_delete_todo_command": {
  const selectedTasks = getSelectedTasks();
  if (
    selectedTasks.length == 0 ||
    selectedTasks.some(task => !cal.acl.userCanDeleteItemsFromCalendar(task.calendar))
  ) {
    return false;
  }
}
